add_filter( 'manage_media_columns', 'perfectpixel_file_size_column' );
add_action( 'manage_media_custom_column', 'perfectpixel_file_size_column_value', 10, 2 );

function perfectpixel_file_size_column( $columns ) {
	$columns['perfectpixel_filesize'] = 'Μέγεθος';
	return $columns;
}

function perfectpixel_file_size_column_value( $column, $attachment_id ) {
	if ( 'perfectpixel_filesize' !== $column ) {
		return;
	}
	$meta  = wp_get_attachment_metadata( $attachment_id );
	$bytes = ! empty( $meta['filesize'] ) ? (int) $meta['filesize'] : 0;
	if ( ! $bytes ) {
		$file  = get_attached_file( $attachment_id );
		$bytes = ( $file && file_exists( $file ) ) ? (int) filesize( $file ) : 0;
	}
	echo $bytes ? esc_html( size_format( $bytes, 1 ) ) : '&ndash;';
}
